// Antepone "R<nº remota> " al nombre del grupo, p.ej. "V Rancho Cerezuela"
// -> "R87 V Rancho Cerezuela". Si un grupo tiene varias remotas separadas
// por "/" (p.ej. "145/146"), se repite la R en cada una: "R145/R146 ...".
// Si el grupo no está en el mapa, se deja el nombre tal cual (sin remota).
function nombreConRemota(nombreGrupo) {
    if (!nombreGrupo) return nombreGrupo;
    var remota = REMOTA_POR_GRUPO[nombreGrupo];
    return remota ? ('R' + remota.split('/').join('/R') + ' ' + nombreGrupo) : nombreGrupo;
}

self.onInit = function() {
    const $ctx = self.ctx;
    // Carga inicial (primera vez que se monta el widget)
    setTimeout(function() {
        repintarDesdeLocalStorage($ctx);
    }, 150);
    // El calendario avisa con este evento cada vez que se hace clic en una
    // celda nueva -- antes este widget solo leía localStorage UNA vez al
    // cargar, así que si cambiabas de celda sin recargar la página entera,
    // se quedaba con el primer día que se clicó. Ahora se repinta solo.
    handlerCeldaSeleccionada = function(e) {
        repintarDesdeLocalStorage($ctx, e.detail);
    };
    window.addEventListener('riego-celda-seleccionada', handlerCeldaSeleccionada);
    // NUEVO: aviso lanzado por el widget "Comparativa caudales" (dias
    // anteriores) al corregir el signo (+Suma/-Resta) de un caudalimetro
    // para un dia pasado. Este widget (la cabecera "CAUDAL MEDIO") pide su
    // dato UNA SOLA VEZ por dia mostrado (guarda "ultimoDiaPintado" para no
    // repetir la peticion en cada onDataUpdated), asi que sin este aviso se
    // quedaba con el valor de antes de corregir hasta recargar la pagina
    // entera. Si el aviso es para el mismo activo Y el mismo dia que se
    // esta viendo ahora mismo, se resetea esa guarda y se vuelve a pedir.
    handlerCorreccionGuardadaCabecera = function(e) {
        const grupoId = e.detail && e.detail.grupoId;
        const fechaStr = e.detail && e.detail.fechaStr; // 'YYYY-MM-DD'
        if (!grupoId || !fechaStr) return;
        const assetIdActual = localStorage.getItem('riego_asset_id');
        if (!assetIdActual || assetIdActual !== grupoId) return; // no es la entidad que se esta mostrando aqui
        if (!$ctx.timeWindow || !$ctx.timeWindow.minTime) return;
        const fechaMostrada = new Date($ctx.timeWindow.minTime);
        const fechaStrMostrada = fechaMostrada.getFullYear() + '-' +
            String(fechaMostrada.getMonth() + 1).padStart(2, '0') + '-' +
            String(fechaMostrada.getDate()).padStart(2, '0');
        if (fechaStrMostrada !== fechaStr) return; // el dia corregido no es el que se ve ahora
        ultimoDiaPintado = null; // fuerza a que la siguiente llamada vuelva a pedir el dato
        self.onDataUpdated();
    };
    window.addEventListener('riego-correccion-guardada', handlerCorreccionGuardadaCabecera);
    // --- NUEVO: botón "Resumen Toma" -- lleva al estado de dashboard "toma" ---
    // Este widget vive dentro de una ventana de diálogo separada (abierta por
    // el calendario con "Abrir estado del dashboard en cuadro de diálogo
    // separado"). Al pulsar el botón hay que:
    //   1) Leer el grupo de riego actual (localStorage, lo deja escrito el
    //      calendario al hacer clic en una celda).
    //   2) Abrir el estado "toma" pasando ESE grupo como entidad objetivo del
    //      estado -- se hace con el mismo patrón de acciones que el resto del
    //      sistema (actionsApi + action source). En la pestaña "Acciones" del
    //      widget hay que configurar la acción para la clave
    //      "click_resumen_toma" como "Actualizar estado del dashboard" (o
    //      "Abrir estado del dashboard"), estado de destino "toma", y
    //      "Entidad objetivo" = "Entidad seleccionada del widget" para que
    //      recoja el ID que le pasamos aquí abajo.
    //   3) Cerrar el diálogo que contiene este widget. No hay una API pública
    //      documentada para esto en JS de widget, así que se hace a nivel de
    //      DOM: se busca el botón de cerrar del propio diálogo de ThingsBoard
    //      (icono "X" de la cabecera) y se simula el clic; si no se encuentra,
    //      se simula la tecla Escape, que Angular Material usa por defecto
    //      para cerrar diálogos. Es "best effort": si el HTML interno del
    //      diálogo cambia entre versiones de ThingsBoard puede que haya que
    //      ajustar los selectores de cerrarDialogoActual().
    $ctx.$container.find('#btn-resumen-toma').off('click').on('click', function(e) {
        const assetId = localStorage.getItem('riego_asset_id');
        const assetName = localStorage.getItem('riego_asset_name');
        const descriptors = self.ctx.actionsApi.getActionDescriptors('click_resumen_toma');
        let targetEntityId = null;
        if (assetId && assetId !== 'null') {
            targetEntityId = { entityType: 'ASSET', id: assetId };
        }
        if (descriptors && descriptors.length > 0) {
            descriptors.forEach(function(desc) {
                self.ctx.actionsApi.handleWidgetAction(e, desc, targetEntityId, assetName, null, assetName);
            });
        } else if (targetEntityId) {
            $ctx.stateController.openState('toma', { entityId: targetEntityId, entityName: assetName }, false);
        } else {
            $ctx.stateController.openState('toma');
        }
        cerrarDialogoActual();
    });
};
self.actionSources = function() {
    return {
        'click_resumen_toma': { name: 'Click en Resumen Toma', multiple: false }
    };
};
// Best-effort: cierra la ventana de diálogo (Angular Material) dentro de la
// cual está montado este widget, si la hay. Ver comentario más arriba.
function cerrarDialogoActual() {
    try {
        const $ctx = self.ctx;
        const $dialogContainer = $ctx.$container.closest(
            '.mat-dialog-container, .mat-mdc-dialog-container, mat-dialog-container'
        );
        if ($dialogContainer.length === 0) {
            return false;
        }
        const $closeBtn = $dialogContainer.find(
            '[mat-dialog-close], .mat-mdc-dialog-close, .tb-dialog-close-button, [aria-label="Close"], [aria-label="Cerrar"]'
        ).first();
        if ($closeBtn.length > 0) {
            $closeBtn[0].click();
            return true;
        }
        // Fallback: Angular Material cierra el diálogo con Escape por defecto.
        const escEvent = new KeyboardEvent('keydown', {
            key: 'Escape', code: 'Escape', keyCode: 27, which: 27, bubbles: true
        });
        document.dispatchEvent(escEvent);
        return true;
    } catch (err) {
        console.warn('[Resumen Toma] No se pudo cerrar automáticamente el diálogo:', err);
        return false;
    }
}
// ============================================================
// Selector de fechas NATIVO de ThingsBoard (el del dashboard/widget de
// gráfica): esto SÍ dispara self.onDataUpdated, pero solo si el widget
// tiene al menos una clave configurada en la pestaña Data -- por eso hace
// falta añadir una (cualquiera, solo sirve de disparador). Cuando cambia
// la fecha, se pide por API el caudal de la entidad ya seleccionada
// (localStorage) para ESE día concreto.
//
// IMPORTANTE (fix): esta es ahora la ÚNICA fuente de verdad para #v-fecha
// y #v-caudal. Antes, "repintarDesdeLocalStorage" TAMBIÉN escribía en esos
// mismos dos campos (leyendo la clave vieja "riego_ts"/"riego_caudal", que
// solo se actualiza al hacer clic en una celda del calendario) y las dos
// funciones competían por pintar el mismo sitio sin ningún orden garantizado
// -- por eso, al usar "Ir a ayer" o las flechas del selector de fecha (que
// NO tocan "riego_ts"), a veces se veía la fecha/caudal de un clic de
// calendario antiguo en vez del día real seleccionado, o el "salto" de más
// de un día que se veía al navegar. Ahora "repintarDesdeLocalStorage" solo
// pinta nombre y comentario (ver más abajo); la fecha y el caudal dependen
// exclusivamente de la ventana de tiempo real del dashboard.
// ============================================================
var ultimoDiaPintado = null;
self.onDataUpdated = function() {
    const $ctx = self.ctx;
    if (!$ctx.timeWindow || !$ctx.timeWindow.minTime) return;
    const assetId = localStorage.getItem('riego_asset_id');
    if (!assetId || assetId === 'null') return;
    const fecha = new Date($ctx.timeWindow.minTime);
    const inicioDia = new Date(fecha.getFullYear(), fecha.getMonth(), fecha.getDate(), 0, 0, 0).getTime();
    const finDia = inicioDia + 86400000 - 1000;

    // Evita relanzar la misma petición/pintado si el widget recibe varios
    // "onDataUpdated" seguidos para el mismo día (p.ej. al abrir el diálogo,
    // ThingsBoard puede disparar esto más de una vez con el mismo timewindow).
    if (ultimoDiaPintado === inicioDia) return;
    ultimoDiaPintado = inicioDia;

    $ctx.$container.find('#v-fecha').text(
        String(fecha.getDate()).padStart(2, '0') + '/' +
        String(fecha.getMonth() + 1).padStart(2, '0') + '/' +
        fecha.getFullYear()
    );
    const hoy = new Date();
    const esHoy = (fecha.getFullYear() === hoy.getFullYear() && fecha.getMonth() === hoy.getMonth() && fecha.getDate() === hoy.getDate());
    const url = `/api/plugins/telemetry/ASSET/${assetId}/values/timeseries?keys=caudal_fijado,caudal_manual,media_proyectada&startTs=${inicioDia}&endTs=${finDia}&limit=200`;
    $ctx.http.get(url).subscribe(function(data) {
        // Misma prioridad que en el resto del sistema: manual > (si es hoy)
        // proyectada > fijado. Se toma el ultimo valor de cada lista.
        function ultimo(arr) {
            if (!arr || arr.length === 0) return null;
            return parseFloat(arr[arr.length - 1].value);
        }
        const manual = ultimo(data.caudal_manual);
        const proyectada = ultimo(data.media_proyectada);
        const fijado = ultimo(data.caudal_fijado);
        let valor = null;
        if (manual !== null && !isNaN(manual)) { valor = manual; }
        else if (esHoy && proyectada !== null && !isNaN(proyectada)) { valor = proyectada; }
        else if (fijado !== null && !isNaN(fijado)) { valor = fijado; }
        $ctx.$container.find('#v-caudal').text(valor !== null ? Math.round(valor) : '0');
        // El comentario no se recalcula aqui -- si tambien hace falta para
        // fechas distintas del clic original, dimelo y lo añado.
    }, function() {
        $ctx.$container.find('#v-caudal').text('0');
    });
};
function repintarDesdeLocalStorage($ctx, detalle) {
    // Si viene del evento ya trae los datos frescos; si no (carga inicial),
    // se leen de localStorage como se hacía siempre.
    // NOTA: ya NO se toca aquí #v-fecha ni #v-caudal -- eso lo controla
    // exclusivamente "onDataUpdated" a partir de la ventana de tiempo real
    // (ver comentario más arriba). Esta función solo se encarga de nombre
    // y comentario, que no tienen ningún equivalente "por día" propio.
    const nombre = detalle ? detalle.assetName : localStorage.getItem('riego_asset_name');
    const comentario = detalle ? detalle.comentario : localStorage.getItem('riego_comentario');
     if (nombre && nombre !== "null") {
        const nombreCompleto = nombreConRemota(nombre);
        $ctx.$container.find('#v-nombre').text(nombreCompleto).attr('title', nombreCompleto);
    }
    // La fila de Entidad/Fecha/Caudal NUNCA se mueve ni cambia de alto --
    // el comentario es un bloque aparte, debajo, que solo aparece si hay
    // algo que mostrar. Si es muy largo, tiene su propio scroll (el
    // "COMENTARIO:" y todo lo de arriba se quedan fijos en su sitio).
    if (comentario && comentario !== "null" && comentario.trim() !== "") {
        $ctx.$container.find('#v-comentario-texto').html(formatearComentario(comentario));
        $ctx.$container.find('#v-comentario-fila').css('display', 'block');
    } else {
        $ctx.$container.find('#v-comentario-fila').css('display', 'none');
    }
}
function escapeHtml(texto) {
    return texto
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
}
// El comentario puede traer varias partes juntas separadas por " | "
// (comentario del admin + nota del guarda). En cada parte, si viene con
// formato "Nombre: texto", el nombre se resalta en negrita para que se
// vea de un vistazo quién ha escrito qué.
function formatearComentario(comentario) {
    const partes = comentario.split(' | ');
    const partesHtml = partes.map(function(parte) {
        const idx = parte.indexOf(': ');
        if (idx === -1) { return escapeHtml(parte); }
        const nombre = parte.slice(0, idx);
        const resto = parte.slice(idx + 2);
        return '<b>' + escapeHtml(nombre) + ':</b> ' + escapeHtml(resto);
    });
    return partesHtml.join('<br>');
}
self.onDestroy = function() {
    if (handlerCeldaSeleccionada) {
        window.removeEventListener('riego-celda-seleccionada', handlerCeldaSeleccionada);
        handlerCeldaSeleccionada = null;
    }
    if (handlerCorreccionGuardadaCabecera) {
        window.removeEventListener('riego-correccion-guardada', handlerCorreccionGuardadaCabecera);
        handlerCorreccionGuardadaCabecera = null;
    }
};

